begin;
create extension if not exists pgtap with schema extensions;
grant usage on schema extensions to cuevo_api;
set local search_path=extensions,pg_catalog;
select no_plan();
select ok(to_regclass('app.current_submissions')is not null,'current submission state exists beside immutable source');
select ok(to_regclass('app.quiz_versions')is not null,'teacher question versions persist privately');
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Lifecycle golden','Synthetic','PUBLISHED');
insert into app.assessments(school_id,id,course_id,created_by,title,instructions,max_score,academic_reference_id)values('10000000-0000-4000-8000-000000000001','91100000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Explain','School text task',10,'61000000-0000-4000-8000-000000000001'),('10000000-0000-4000-8000-000000000001','91100000-0000-4000-8000-000000000002','91000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Quiz','School quiz',10,'61000000-0000-4000-8000-000000000001');
create temporary table lifecycle_ids(submission uuid,returned uuid,revised uuid,quiz uuid,attempt uuid);grant select,insert,update on lifecycle_ids to cuevo_api;
set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);
select lives_ok($$select internal.save_submission_draft('91100000-0000-4000-8000-000000000001','First draft',0)$$,'learner saves actual draft');
select throws_ok($$select internal.save_submission_draft('91100000-0000-4000-8000-000000000001','Stale draft',0)$$,'22023',null,'draft version rejects stale edit');
insert into lifecycle_ids(submission)select internal.create_learning_submission('91100000-0000-4000-8000-000000000001','Original source');
select throws_ok($$select internal.create_learning_submission('91100000-0000-4000-8000-000000000001','Second without return')$$,'22023',null,'second source requires a teacher return');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
update lifecycle_ids set returned=internal.return_learning_submission(submission,'Explain the checking step.',1);
select is((select state from app.current_submissions where submission_id=(select submission from lifecycle_ids)),'RETURNED','teacher return changes pointer state only');
select is("authorization".current_submission_open('10000000-0000-4000-8000-000000000001',(select submission from lifecycle_ids)),false,'returned source is closed to new academic writes');
select throws_ok($$select internal.mark_submission((select submission from lifecycle_ids),0,'Returned source',1,0,true)$$,'22023',null,'academic mark cannot use returned source');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
update lifecycle_ids set revised=internal.resubmit_learning_submission(submission,returned,'Revised explanation',1);
select is((select revision from app.submissions where id=(select revised from lifecycle_ids)),2,'resubmission creates source revision two');
select is((select previous_submission_id from app.submissions where id=(select revised from lifecycle_ids)),(select submission from lifecycle_ids),'new source pins immutable prior work');
select is((select return_id from app.submissions where id=(select revised from lifecycle_ids)),(select returned from lifecycle_ids),'new source pins actual human feedback return');
select is((select content from app.submissions where id=(select submission from lifecycle_ids)),'Original source','original submitted content remains unchanged');
select ok(exists(select 1 from jsonb_array_elements(internal.read_submission_page(100,null,(select revised from lifecycle_ids))->'items')item where item->>'id'=(select submission::text from lifecycle_ids)and item->>'content'='Original source'),'bounded source history retains original submitted work');
select ok(not exists(select 1 from jsonb_array_elements(internal.read_submission_page(100,null,null)->'items')item where item->>'id'=(select submission::text from lifecycle_ids)),'current submission queue excludes superseded source');
select throws_ok($$select internal.resubmit_learning_submission((select submission from lifecycle_ids),(select returned from lifecycle_ids),'Duplicate revision',1)$$,'22023',null,'stale prior source cannot create third revision');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000013',true);
select throws_ok($$select internal.read_submission_page(100,null,(select revised from lifecycle_ids))$$,'42501',null,'peer cannot read historical source');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select throws_ok('select internal.read_submission_page(100,null,null)','42501',null,'parent cannot retrieve raw source page');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select throws_ok($$select internal.mark_submission((select submission from lifecycle_ids),0,'Superseded source',1,0,true)$$,'22023',null,'academic mark cannot use superseded source');
select internal.close_learning_submission((select revised from lifecycle_ids),2);
select throws_ok($$select internal.mark_submission((select revised from lifecycle_ids),0,'Closed source',1,0,true)$$,'22023',null,'academic mark cannot use closed source');
reset role;update app.enrollments set status='revoked'where school_id='10000000-0000-4000-8000-000000000001'and class_id='30000000-0000-4000-8000-000000000001'and student_actor_id='20000000-0000-4000-8000-000000000012';
set local role cuevo_api;
select throws_ok($$select internal.read_submission_page(100,null,(select revised from lifecycle_ids))$$,'42501',null,'teacher loses source history when learner leaves this class');
select ok(not exists(select 1 from jsonb_array_elements(internal.read_submission_page(100,null,null)->'items')item where item->>'id'=(select revised::text from lifecycle_ids)),'teacher current page excludes revoked course enrollment');
reset role;update app.enrollments set status='active'where school_id='10000000-0000-4000-8000-000000000001'and class_id='30000000-0000-4000-8000-000000000001'and student_actor_id='20000000-0000-4000-8000-000000000012';
set local role cuevo_api;
update lifecycle_ids set quiz=internal.create_quiz_version('91100000-0000-4000-8000-000000000002','school-1','[{"key":"q1","prompt":"Select the example","options":[{"key":"a","label":"First"},{"key":"b","label":"Second"}],"correctOptionKey":"b"}]');
select lives_ok($$select internal.publish_quiz_version('91100000-0000-4000-8000-000000000002',(select quiz from lifecycle_ids),1)$$,'teacher publishes immutable quiz version');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select is((select count(*)from app.quiz_versions),0::bigint,'student cannot read private answer-key rows');
select ok(not(internal.read_published_quiz('91100000-0000-4000-8000-000000000002')::text like'%correctOptionKey%'),'safe quiz read omits answer key');
select throws_ok($$select internal.submit_quiz_attempt('91100000-0000-4000-8000-000000000002',(select quiz from lifecycle_ids),'[]')$$,'22023',null,'quiz requires explicit answer for every question');
update lifecycle_ids set attempt=internal.submit_quiz_attempt('91100000-0000-4000-8000-000000000002',quiz,'[{"questionKey":"q1","optionKey":"a"}]');
select is((select checked_answers->0->>'status'from app.quiz_attempts where id=(select attempt from lifecycle_ids)),'INCORRECT','deterministic checking records the actual answer');
select is((select count(*)from app.result_revisions where submission_id in(select submission_id from app.quiz_attempts where id=(select attempt from lifecycle_ids))),0::bigint,'quiz checking never releases academic grade');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select internal.configure_assessment_availability('91100000-0000-4000-8000-000000000001',null,null,true,'CLOSED',1);
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select throws_ok($$select internal.save_submission_draft('91100000-0000-4000-8000-000000000001','Unavailable',1)$$,'22023',null,'closed availability denies learner write');
reset role;
select throws_ok($$update app.submissions set content='Overwrite'where id=(select submission from lifecycle_ids)$$,'55000',null,'source immutability remains enforced');
select throws_ok($$update app.submission_returns set feedback='Overwrite'where id=(select returned from lifecycle_ids)$$,'55000',null,'human return evidence is immutable');
select throws_ok($$update app.quiz_versions set questions='[]'where id=(select quiz from lifecycle_ids)$$,'55000',null,'published question version remains immutable');
select ok(not exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='app'and c.relkind='r'and c.relname in('current_submissions','submission_drafts','submission_returns','submission_closures','quiz_versions','published_quizzes','quiz_attempts')and(not c.relrowsecurity or not c.relforcerowsecurity)),'new learning tables force RLS');
select *from finish();rollback;
